contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target, uint amount, bytes memory data) public payable {
        require(amount <= address(c).balance, "amount must not exceed C's balance");

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.sendMoney(target, amount, data); if (__ESBMC_reverted()) return;

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(beforeBalance - amount == afterBalance || beforeBalance - amount < afterBalance);
    }
}

